1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    [data-color="green"] { --fg: #16a34a; }
31	    [data-color="amber"] { --fg: #d97706; }
32	    [data-color="violet"] { --fg: #7c3aed; }
33	    [data-color="cyan"] { --fg: #0891b2; }
34	    @media (prefers-color-scheme: dark) {
35	      :root {
36	        --bg: #111;
37	        --text: #d1d5db;
38	        --fg: #93c5fd;
39	        --shadow: rgba(0, 0, 0, 0.6);
40	        --kbd-bg: rgba(255, 255, 255, 0.15);
41	      }
42	      [data-color="red"] { --fg: #fca5a5; }
43	      [data-color="green"] { --fg: #86efac; }
44	      [data-color="amber"] { --fg: #fcd34d; }
45	      [data-color="violet"] { --fg: #c4b5fd; }
46	      [data-color="cyan"] { --fg: #67e8f9; }
47	    }
48	    @media (prefers-contrast: more) {
49	      :root {
50	        --shadow: rgba(0, 0, 0, 0.9);
51	        --drop: drop-shadow(0 2px 8px var(--shadow));
52	      }
53	      .hint {
54	        opacity: 1 !important;
55	      }
56	    }
57	    @media (forced-colors: active) {
58	      svg circle {
59	        stroke: CanvasText;
60	        stroke-width: 2;
61	      }
62	    }
63	    body {
64	      min-height: 100vh;
65	      min-height: 100dvh;
66	      display: grid;
67	      place-items: center;
68	      padding: 1rem;
69	      background: var(--bg);
70	      color: var(--text);
71	      font-family: system-ui, -apple-system, sans-serif;
72	    }
73	    main {
74	      width: 100%;
75	      display: flex;
76	      flex-direction: column;
77	      align-items: center;
78	      text-align: center;
79	    }
80	    button {
81	      display: block;
82	      width: min(360px, 100%, 60vh);
83	      aspect-ratio: 1;
84	      border: 0;
85	      border-radius: 50%;
86	      background: none;
87	      color: var(--fg);
88	      cursor: pointer;
89	      touch-action: manipulation;
90	      -webkit-tap-highlight-color: transparent;
91	      transition: color 0.4s ease;
92	      position: relative;
93	      min-height: 48px;
94	      min-width: 48px;
95	    }
96	    .color-indicator {
97	      position: absolute;
98	      bottom: 12%;
99	      right: 12%;
100	      width: 1rem;
101	      height: 1rem;
102	      border-radius: 50%;
103	      background: currentColor;
104	      border: 2px solid var(--bg);
105	      box-shadow: 0 2px 4px var(--shadow);
106	    }
107	    .no-transition,
108	    .no-transition svg,
109	    .no-transition .color-indicator {
110	      transition: none !important;
111	    }
112	    button:focus-visible {
113	      outline: 3px solid currentColor;
114	      /* Must clear the scaled-up circle (up to 9px) or the ring merges with it */
115	      outline-offset: 12px;
116	    }
117	    svg {
118	      display: block;
119	      width: 100%;
120	      height: 100%;
121	      overflow: visible;
122	      opacity: 0.85;
123	      filter: var(--drop);
124	      transition: opacity 0.3s ease;
125	    }
126	    button:active svg,
127	    button:focus-visible svg {
128	      opacity: 1;
129	    }
130	    @keyframes pulse {
131	      0% {
132	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
133	      }
134	      100% {
135	        filter: var(--drop) drop-shadow(0 0 0 transparent);
136	      }
137	    }
138	    @media (hover: hover) {
139	      button:hover svg {
140	        opacity: 1;
141	      }
142	    }
143	    @media (prefers-reduced-motion: no-preference) {
144	      svg {
145	        transition:
146	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
147	          opacity 0.3s ease;
148	      }
149	      button:focus-visible svg {
150	        transform: scale(1.05);
151	      }
152	      button:active svg {
153	        transform: scale(0.97);
154	      }
155	      button.color-changed svg {
156	        animation: pulse 0.5s ease-out;
157	      }
158	    }
159	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
160	      button:hover:not(:active) svg {
161	        transform: scale(1.05);
162	      }
163	    }
164	    .visually-hidden {
165	      position: absolute;
166	      width: 1px;
167	      height: 1px;
168	      overflow: hidden;
169	      clip-path: inset(50%);
170	      white-space: nowrap;
171	    }
172	    .status {
173	      margin-top: 2rem;
174	      font-weight: 600;
175	    }
176	    .hint {
177	      margin-top: 0.25rem;
178	      font-size: 0.875rem;
179	      opacity: 1;
180	    }
181	    .help-button {
182	      margin-left: 0.5rem;
183	      display: inline-block;
184	      width: 1.25rem;
185	      height: 1.25rem;
186	      line-height: 1.25rem;
187	      border-radius: 50%;
188	      background: var(--kbd-bg);
189	      border: 1px solid currentColor;
190	      color: var(--text);
191	      cursor: help;
192	      font-size: 0.75rem;
193	      font-weight: bold;
194	      text-align: center;
195	      transition: all 0.2s ease;
196	    }
197	    .help-button:hover {
198	      background: currentColor;
199	      color: var(--bg);
200	    }
201	    .keys {
202	      display: none;
203	    }
204	    .keys.visible {
205	      display: inline;
206	    }
207	    @media (hover: none) and (pointer: coarse) {
208	      .hint .keys {
209	        display: none !important;
210	      }
211	      .help-button {
212	        display: none;
213	      }
214	    }
215	    kbd {
216	      display: inline-block;
217	      padding: 0.125rem 0.375rem;
218	      background: var(--kbd-bg);
219	      border: 1px solid transparent;
220	      border-radius: 0.25rem;
221	      font-family: monospace;
222	      font-size: 0.75em;
223	    }
224	  </style>
225	</head>
226	<body>
227	  <main>
228	    <h1 class="visually-hidden">Animated Circle</h1>
229	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
230	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
231	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
232	      </svg>
233	      <span class="color-indicator" aria-hidden="true"></span>
234	    </button>
235	    <p class="status" id="status" role="status" aria-atomic="true" aria-live="polite">Blue</p>
236	    <p class="hint" id="hint"><span class="verb">Click</span> to cycle • Double-click reset<span class="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span> <button type="button" class="help-button" aria-expanded="false" title="Show keyboard shortcuts">?</button></p>
237	  </main>
238	  <script>
239	    const button = document.querySelector('button');
240	    const status = document.querySelector('.status');
241	    const helpButton = document.querySelector('.help-button');
242	    const hint = document.querySelector('.hint');
243	    const keyHint = document.querySelector('.keys');
244	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
245	    const colorHex = {
246	      blue: '#2563eb', red: '#dc2626', green: '#16a34a',
247	      amber: '#d97706', violet: '#7c3aed', cyan: '#0891b2'
248	    };
249	    const storageKey = 'circle-color';
250	    const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
251	
252	    // Safely retrieve saved color from localStorage, returning null if unavailable
253	    function loadColor() {
254	      try {
255	        return localStorage.getItem(storageKey);
256	      } catch {
257	        return null;
258	      }
259	    }
260	
261	    // Safely save color to localStorage, silently failing if unavailable
262	    function saveColor(color) {
263	      try {
264	        localStorage.setItem(storageKey, color);
265	      } catch {}
266	    }
267	
268	    const savedColor = loadColor();
269	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
270	
271	    // Apply current color to button and update status display
272	    function applyColor() {
273	      const color = colors[index];
274	      if (color === 'blue') {
275	        delete button.dataset.color;
276	      } else {
277	        button.dataset.color = color;
278	      }
279	      const displayName = color[0].toUpperCase() + color.slice(1);
280	      const hexCode = colorHex[color];
281	      status.textContent = displayName;
282	      button.setAttribute('aria-label', `Change circle color (currently ${displayName} ${hexCode})`);
283	    }
284	
285	    // Cycle color by step amount and trigger pulse animation
286	    function changeColor(step) {
287	      const next = (index + step + colors.length) % colors.length;
288	      // Home/End at the boundary shouldn't pulse or rewrite storage
289	      if (next === index) return;
290	      index = next;
291	      applyColor();
292	      saveColor(colors[index]);
293	
294	      // Haptic feedback for supported devices
295	      if (navigator.vibrate) navigator.vibrate(50);
296	
297	      // With reduced motion no animation runs, so animationend would never clear the class
298	      if (reducedMotion.matches) return;
299	      button.classList.remove('color-changed');
300	      void button.offsetWidth;
301	      button.classList.add('color-changed');
302	    }
303	
304	    applyColor();
305	    // Double rAF ensures paint completes before enabling animations
306	    requestAnimationFrame(() => requestAnimationFrame(() => {
307	      button.classList.remove('no-transition');
308	    }));
309	
310	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
311	    const hoverQuery = matchMedia('(hover: none)');
312	    const verbSpan = document.querySelector('.hint .verb');
313	    function updateVerb() {
314	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
315	    }
316	    updateVerb();
317	    hoverQuery.addEventListener('change', updateVerb);
318	
319	    // Space and Enter activate through the native click, but keyboard-synthesized
320	    // clicks don't reliably carry shiftKey, so remember it from the key events
321	    let shiftHeld = false;
322	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
323	    // Space clicks on keyup; Enter already clicked on keydown, so updating
324	    // shiftHeld on Enter's keyup would leak into the next mouse click
325	    button.addEventListener('keyup', (event) => {
326	      if (event.key === ' ') shiftHeld = event.shiftKey;
327	    });
328	    button.addEventListener('blur', () => {
329	      shiftHeld = false;
330	    });
331	
332	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
333	    button.addEventListener('keydown', (event) => {
334	      if (isActivationKey(event)) {
335	        // Holding Enter would otherwise fire a click on every repeat; no click
336	        // follows to reset shiftHeld, so setting it here would leak into the
337	        // next mouse click
338	        if (event.repeat) {
339	          if (event.key === 'Enter') event.preventDefault();
340	          return;
341	        }
342	        shiftHeld = event.shiftKey;
343	        return;
344	      }
345	      if (event.altKey || event.ctrlKey || event.metaKey) return;
346	      if (event.key in keySteps) {
347	        event.preventDefault();
348	        changeColor(keySteps[event.key]);
349	      } else if (event.key === 'Home') {
350	        event.preventDefault();
351	        changeColor(-index);
352	      } else if (event.key === 'End') {
353	        event.preventDefault();
354	        changeColor(colors.length - 1 - index);
355	      }
356	    });
357	    button.addEventListener('click', (event) => {
358	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
359	      shiftHeld = false;
360	    });
361	    button.addEventListener('animationend', () => {
362	      button.classList.remove('color-changed');
363	    });
364	    button.addEventListener('dblclick', (event) => {
365	      event.preventDefault();
366	      if (index !== 0) {
367	        index = 0;
368	        applyColor();
369	        saveColor(colors[index]);
370	        if (!reducedMotion.matches) {
371	          button.classList.remove('color-changed');
372	          void button.offsetWidth;
373	          button.classList.add('color-changed');
374	        }
375	      }
376	    });
377	    helpButton.addEventListener('click', (event) => {
378	      event.preventDefault();
379	      event.stopPropagation();
380	      const isExpanded = helpButton.getAttribute('aria-expanded') === 'true';
381	      keyHint.classList.toggle('visible');
382	      helpButton.setAttribute('aria-expanded', !isExpanded);
383	    });
384	    // Show keyboard shortcuts by default on desktop
385	    if (!hoverQuery.matches) {
386	      keyHint.classList.add('visible');
387	      helpButton.setAttribute('aria-expanded', 'true');
388	    }
389	    // Sync color across tabs when storage changes
390	    addEventListener('storage', (event) => {
391	      // key is null when another tab calls localStorage.clear()
392	      if (event.key !== storageKey && event.key !== null) return;
393	      const newIndex = colors.indexOf(event.newValue);
394	      index = newIndex === -1 ? 0 : newIndex;
395	      applyColor();
396	    });
397	  </script>
398	</body>
399	</html>
